-- Teach-card explanations for parts-of-speech questions that had none.
-- Only fills empty ones, so anything edited in the parent area is kept.
UPDATE "Item" SET "context" = 'A noun names a person, place, or thing. ''School'' is a place. ''Run'' is an action (verb), ''quickly'' tells how (adverb), and ''bright'' describes (adjective).', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-004' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = 'A verb is an action word: something you can do. You can jump. ''Tree'' is a thing (noun), ''tall'' describes (adjective), and ''above'' tells where (preposition).', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-005' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = 'An adjective describes a noun. ''Shiny'' tells what something looks like: shiny shoes. ''Shine'' is a verb, and ''shoes'' and ''shop'' are nouns.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-006' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = '''Sisters'' names people, so it''s a noun. ''She'' is who the sentence is about, but it''s a pronoun: a word that stands in for a noun or a name. ''Has'' is a verb and ''three'' tells how many.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-007' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = '''Cried'' is what the baby did, so it''s the verb. ''Baby'' and ''night'' are nouns.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-008' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = 'An adverb tells how, when, or where something happens. ''Beautifully'' tells how the bird sang. Many adverbs end in -ly.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g4-002' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = 'Pronouns stand in for nouns: they, us, we, she, it. ''Keys'' names things, so it''s a noun, not a pronoun.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g4-004' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = '''Softly'' tells how something is done (speak softly), so it''s an adverb. ''Soft'' is an adjective, ''softness'' is a noun, and ''soften'' is a verb.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g4-005' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = '''Slowly'' tells how the man walked, so it''s the adverb. ''Old'' describes the man, so it''s an adjective.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g4-006' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = 'A preposition shows where something is or goes compared to something else: through, under, over, beside. They walked through the park.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g5-002' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = 'A conjunction joins words or ideas. ''But'' joins ''She wanted to go'' and ''it was raining.'' Others are and, or, so, and because.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g5-004' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = '''Beneath'' shows where something is (beneath the bed), so it''s a preposition.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g5-005' AND ("context" IS NULL OR "context" = '');
UPDATE "Item" SET "context" = '''Because'' joins two ideas and gives a reason (I stayed inside because it rained), so it''s a conjunction.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g5-006' AND ("context" IS NULL OR "context" = '');
